    }
    return result;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    TreeNode<T> parent = node.getParent();
    TreeNode<T> grandParent = parent.getParent();
    TreeNode<T> sibling = parent.getSibling();

    // Case 1: node is the root node
    if (grandParent == null) {
        node.setParent(null);
        return node;
    }

    // Case 2: node has a sibling
    if (sibling != null) {
        sibling.setParent(grandParent);
    }

    // Case 3: node has no sibling
    if (sibling == null) {
        parent.setParent(null);
    }

    // Case 4: node is the left child of its parent
    if (parent.getLeftChild() == node) {
        parent.setLeftChild(null);
    }

    // Case 5: node is the right child of its parent
    if (parent.getRightChild() == node) {
        parent.setRightChild(null);
    }

    // Case 6: node is the left child of its grandparent
    if (grandParent.getLeftChild() == parent) {
        grandParent.setLeftChild(node);
    }

    // Case 7: node is the right child of its grandparent
    if (grandParent.getRightChild() == parent) {
        grandParent.setRightChild(node);
    }

    // Case 8: node has no grandparent
    if (grandParent == null) {
        node.setParent(null);
        return node;
    }

    return node;
}

public static void addToClassPath(Vector<URL> cpV, String dir) {
    try {
        File dirFile = new File(dir);
        if (!dirFile.isDirectory()) {
            throw new IllegalArgumentException("The specified directory does not exist or is not a directory");
        }
        File[] jarFiles = dirFile.listFiles(new FilenameFilter() {
            @Override
            public boolean accept(File dir, String name) {
                return name.endsWith(".jar");
            }
        });
        for (File jarFile : jarFiles) {
            cpV.add(jarFile.toURI().toURL());
        }
    } catch (MalformedURLException e) {
        throw new IllegalArgumentException("Invalid URL", e);
    }
}

public String format(LoggingEvent event) {
    // Step 1: Initialize the conversion pattern
    String conversionPattern = event.getConversionPattern();

    // Step 2: Initialize the formatted string
    String formattedString = "";

    // Step 3: Iterate over the conversion pattern and replace placeholders with event data
    for (int i = 0; i < conversionPattern.length(); i++) {
        char c = conversionPattern.charAt(i);
        if (c == '%') {
            i++;
            c = conversionPattern.charAt(i);
            switch (c) {
                case 'd':
                    formattedString += event.getDate();
                    break;
                case 't':
                    formattedString += event.getThreadName();
                    break;
                case 'l':
                    formattedString += event.getLevel();
                    break;
                case 'm':
                    formattedString += event.getMessage();
                    break;
                case 'n':
                    formattedString += event.getNewLine();
                    break;
                default:
                    formattedString += c;
                    break;
            }
        } else {
            formattedString += c;
        }
    }

    // Step 4: Return the formatted string
    return formattedString;
}

