public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Check if the target graph is null
    if (target == null) {
        throw new IllegalArgumentException("Target graph cannot be null");
    }

    // Check if the result map is null
    if (resultMap == null) {
        throw new IllegalArgumentException("Result map cannot be null");
    }

    // Get the number of vertices in the target graph
    int numVertices = target.getNumVertices();

    // Get the number of edges in the target graph
    int numEdges = target.getNumEdges();

    // Check if the number of vertices is even
    if (numVertices % 2 != 0) {
        throw new IllegalArgumentException("Number of vertices must be even");
    }

    // Check if the number of edges is even
    if (numEdges % 2 != 0) {
        throw new IllegalArgumentException("Number of edges must be even");
    }

    // Create a new graph with the same number of vertices as the target graph
    Graph<V,E> newGraph = new Graph<>(numVertices);

    // Add edges to the new graph
    for (int i = 0; i < numEdges; i++) {
        // Get the source and target vertices for the current edge
        V source = target.getEdgeSource(i);
        V target = target.getEdgeTarget(i);

        // Check if the source and target vertices are in the result map
        if (!resultMap.containsKey(source) || !resultMap.containsKey(target)) {
            throw new IllegalArgumentException("Source and target vertices must be in the result map");
        }

        // Get the corresponding vertices in the new graph
        V newSource = resultMap.get(source);
        V newTarget = resultMap.get(target);

        // Add the edge to the new graph
        newGraph.addEdge(newSource, newTarget);
    }

    // Return the new graph
    return newGraph;
}

