public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Check if the input string is null or empty
    if (str == null || str.length() == 0) {
        throw new IllegalArgumentException("Input string cannot be null or empty");
    }

    // Check if the WriteSession is null
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }

    // Check if the LinkedBuffer is null
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    // Write the UTF-8 encoded bytes to the LinkedBuffer
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            lb.writeByte((byte) c);
        } else if (c <= 0x7FF) {
            lb.writeByte((byte) (0xC0 | (c >> 6)));
            lb.writeByte((byte) (0x80 | (c & 0x3F)));
        } else if (c <= 0xFFFF) {
            lb.writeByte((byte) (0xE0 | (c >> 12)));
            lb.writeByte((byte) (0x80 | ((c >> 6) & 0x3F)));
            lb.writeByte((byte) (0x80 | (c & 0x3F)));
        } else {
            lb.writeByte((byte) (0xF0 | (c >> 18)));
            lb.writeByte((byte) (0x80 | ((c >> 12) & 0x3F)));
            lb.writeByte((byte) (0x80 | ((c >> 6) & 0x3F)));
            lb.writeByte((byte) (0x80 | (c & 0x3F)));
        }
    }

    return lb;
}

public void removeFromTreeEdgeList() {
    // Check if the edge is not null
    if (this == null) {
        throw new IllegalArgumentException("Edge cannot be null");
    }

    // Check if the edge is not already removed
    if (this.removed) {
        throw new IllegalStateException("Edge is already removed");
    }

    // Remove the edge from the tree edge list
    this.treeEdgeList.remove(this);

    // Set the removed flag to true
    this.removed = true;
}

public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        throw new IllegalArgumentException("Key not found: " + key);
    }
    return value.replaceAll("\\$\\{([^}]+)\\}", (match) -> {
        String varName = match.group(1);
        String varValue = props.getProperty(varName);
        if (varValue == null) {
            throw new IllegalArgumentException("Variable not found: " + varName);
        }
        return varValue;
    });
}

