public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    // Check if the path component is null or empty
    if (u.getPath() == null || u.getPath().isEmpty()) {
        return pathSegments;
    }

    // Get the path component as a string
    String path = u.getPath();

    // Check if the path component is an absolute path component
    if (path.startsWith("/")) {
        path = path.substring(1);
    }

    // Split the path component into path segments
    String[] pathSegmentStrings = path.split("/");

    // Decode the path segments if necessary
    if (decode) {
        for (int i = 0; i < pathSegmentStrings.length; i++) {
            pathSegmentStrings[i] = URLDecoder.decode(pathSegmentStrings[i], StandardCharsets.UTF_8);
        }
    }

    // Create the path segments
    for (String pathSegmentString : pathSegmentStrings) {
        pathSegments.add(new PathSegmentImpl(pathSegmentString));
    }

    return pathSegments;
}

