public String format(final LoggingEvent event) {
    // Check if the event is null
    if (event == null) {
        throw new IllegalArgumentException("Event cannot be null");
    }

    // Get the event's message
    String message = event.getMessage();

    // Check if the message is null or empty
    if (message == null || message.isEmpty()) {
        throw new IllegalArgumentException("Event message cannot be null or empty");
    }

    // Get the event's timestamp
    long timestamp = event.getTimestamp();

    // Check if the timestamp is valid
    if (timestamp <= 0) {
        throw new IllegalArgumentException("Event timestamp must be a positive value");
    }

    // Get the event's level
    Level level = event.getLevel();

    // Check if the level is null
    if (level == null) {
        throw new IllegalArgumentException("Event level cannot be null");
    }

    // Get the event's logger name
    String loggerName = event.getLoggerName();

    // Check if the logger name is null or empty
    if (loggerName == null || loggerName.isEmpty()) {
        throw new IllegalArgumentException("Event logger name cannot be null or empty");
    }

    // Get the event's thread name
    String threadName = event.getThreadName();

    // Check if the thread name is null or empty
    if (threadName == null || threadName.isEmpty()) {
        throw new IllegalArgumentException("Event thread name cannot be null or empty");
    }

    // Get the event's throwable
    Throwable throwable = event.getThrowable();

    // Check if the throwable is null
    if (throwable == null) {
        throw new IllegalArgumentException("Event throwable cannot be null");
    }

    // Get the event's throwable stack trace
    StackTraceElement[] stackTrace = throwable.getStackTrace();

    // Check if the stack trace is null or empty
    if (stackTrace == null || stackTrace.length == 0) {
        throw new IllegalArgumentException("Event throwable stack trace cannot be null or empty");
    }

    // Format the event
    StringBuilder sb = new StringBuilder();
    sb.append(timestamp).append(" ").append(level).append(" ").append(loggerName).append(" ").append(threadName).append(" - ").append(message).append("\n");
    for (StackTraceElement element : stackTrace) {
        sb.append(element.toString()).append("\n");
    }
    return sb.toString();
}

