public byte[] toByteArray() {
    // Initialize an empty byte array to store the contents of the buffer(s)
    byte[] result = new byte[0];

    // Iterate through each buffer in the list
    for (ByteBuffer buffer : buffers) {
      // Get the current position of the buffer
      int pos = buffer.position();

      // Get the current limit of the buffer
      int limit = buffer.limit();

      // Check if the buffer has remaining bytes
      if (pos < limit) {
        // Get the remaining bytes in the buffer
        byte[] bytes = new byte[limit - pos];
        buffer.get(bytes);

        // Append the remaining bytes to the result array
        result = Arrays.copyOf(result, result.length + bytes.length);
        System.arraycopy(bytes, 0, result, result.length - bytes.length, bytes.length);
      }
    }

    // Return the result array
    return result;
  }

public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            char nextChar = str.charAt(i + 1);
            if (nextChar == 'n') {
                sb.append('\n');
            } else if (nextChar == 't') {
                sb.append('\t');
            } else if (nextChar == 'r') {
                sb.append('\r');
            } else if (nextChar == 'f') {
                sb.append('\f');
            } else if (nextChar == 'b') {
                sb.append('\b');
            } else if (nextChar == '\\') {
                sb.append('\\');
            } else if (nextChar == '\'') {
                sb.append('\'');
            } else if (nextChar == '\"') {
                sb.append('\"');
            } else if (nextChar == 'u') {
                String hexCode = str.substring(i + 2, i + 6);
                sb.append((char) Integer.parseInt(hexCode, 16));
                i += 4;
            } else {
                sb.append(c);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

