public int appendLoopOnAppenders(LoggingEvent event) {
    int numAppended = 0;
    for (Appender appender : getAllAppenders()) {
        try {
            appender.doAppend(event);
            numAppended++;
        } catch (Exception e) {
            // Ignore any exceptions and continue to the next appender
        }
    }
    return numAppended;
}

