private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        throw new IllegalArgumentException("Node cannot be null");
    }
    if (node.next == null) {
        return false;
    }
    node.next.prev = node.prev;
    node.prev.next = node.next;
    node.next = null;
    node.prev = null;
    return true;
}

public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> sequenceRanges = new ArrayList<>();
    for (Profile profile : currentProfiles) {
        for (Segment segment : profile.getSegments()) {
            for (Snapshot snapshot : segment.getSnapshots()) {
                sequenceRanges.add(new SequenceRange(snapshot.getStart(), snapshot.getEnd()));
            }
        }
    }
    return sequenceRanges;
}

