public Edge edgeToNext() {
    if (currentNode == null) {
        throw new IllegalStateException("No current node set");
    }
    if (nextNode == null) {
        throw new IllegalStateException("No next node set");
    }
    if (currentNode.isVirtual()) {
        currentNode = currentNode.getRealNode();
    }
    if (nextNode.isVirtual()) {
