    }
    return new Edge(currentNode, nextNode);
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        throw new IllegalArgumentException("str and substring cannot be null");
    }
    if (index < 0 || index >= str.length()) {
        throw new IndexOutOfBoundsException("Index " + index + " is out of bounds for string of length " + str.length());
    }
    if (substring.length() > str.length() - index) {
        return false;
    }
    for (int i = 0; i < substring.length(); i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

